/* Exhale service worker — generated by scripts/generate-sw.mjs. Do not edit dist/sw.js by hand. */
const VERSION = '__VERSION__';
const CACHE = 'exhale-' + VERSION;
const PAGES = __PAGES__; // [{ url: '/curriculum', file: '/curriculum.html' }]
const ASSETS = __ASSETS__;

// Some hosts serve /page, some only /page.html, and some redirect between them.
// Try both, and store a copy without the redirect flag (Safari refuses to serve
// redirected responses for navigations).
async function fetchPage(page) {
  for (const url of [page.url, page.file]) {
    try {
      const res = await fetch(url, { cache: 'no-cache' });
      if (res.ok) return new Response(await res.blob(), { headers: res.headers });
    } catch {}
  }
  throw new Error('Could not fetch ' + page.url);
}

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE);
      await cache.addAll(ASSETS);
      await Promise.all(PAGES.map(async (p) => cache.put(p.url, await fetchPage(p))));
      await self.skipWaiting();
    })(),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(keys.filter((k) => k.startsWith('exhale-') && k !== CACHE).map((k) => caches.delete(k)));
      await self.clients.claim();
    })(),
  );
});

function cleanPath(pathname) {
  let p = pathname.replace(/\.html$/, '').replace(/\/index$/, '').replace(/\/$/, '');
  return p === '' ? '/' : p;
}

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;

  if (req.mode === 'navigate') {
    // App shell: serve the precached page instantly; fall back to the network,
    // then to the home page (the client router takes over from any page).
    event.respondWith(
      (async () => {
        const cache = await caches.open(CACHE);
        const hit = await cache.match(cleanPath(url.pathname));
        if (hit) return hit;
        try {
          return await fetch(req);
        } catch {
          return (await cache.match('/')) || Response.error();
        }
      })(),
    );
    return;
  }

  // Static files are content-hashed: cache first, then network (and keep a copy).
  event.respondWith(
    (async () => {
      const cache = await caches.open(CACHE);
      const hit = await cache.match(req, { ignoreSearch: true });
      if (hit) return hit;
      const res = await fetch(req);
      if (res.ok && res.type === 'basic') cache.put(req, res.clone());
      return res;
    })(),
  );
});
